  // Grasp UI language: `zh-CN` | `en`, or '' when unknown.
  function normLang(v) {
    v = typeof v === 'string' ? v : '';
    if (/^zh/i.test(v)) return 'zh-CN';
    if (/^en/i.test(v)) return 'en';
    return '';
  }

  function stringsFor(l) {
    return /^zh/i.test(l || '') ? STRINGS.zh : STRINGS.en;
  }

